    '''Summarize errors by kind and group; identify extreme error-share groups.'''
    if not errors:
        raise ValueError('errors must not be empty')
    counts_by_kind = {}
    counts_by_group = {}
    for e in errors:
        if 'kind' not in e or 'group' not in e:
            raise ValueError('each error needs kind and group')
